function applyExtendedLanguage() { const english = (state.language || "zh") === "en"; const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode); const translations = [...extendedTranslations].sort((a, b) => Math.max(b[0].length, b[1].length) - Math.max(a[0].length, a[1].length)); nodes.forEach(node => { if (node.parentElement?.closest("script,style")) return; let text = node.nodeValue; translations.forEach(([zh, en]) => { text = text.split(english ? zh : en).join(english ? en : zh); }); if (node.nodeValue !== text) node.nodeValue = text; }); }
