function renderValues() { const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); const c = state.combat; const mission = c ? contracts.find(item => item.id === state.contract) : null; const rows = [["RUNNER ID", state.name], ["LEVEL / XP", `LV ${state.level} // ${state.xp} XP`], ["CREDITS", `₡ ${state.credits.toLocaleString()}`], ["VITAL", `${state.hp} / ${maxHp}`], ["RAM", `${state.ram} / 100`], ["HEAT", `${state.heat}%`], ["REP", `+${state.rep}`], ["CITY", (cities.find(city => city.id === state.city) || cities[0]).name], ["INVENTORY", `體素針 ${state.inventory.medkit} // 醫療箱 ${state.inventory.medbox} // RAM ${state.inventory.ramCell} // 黑盒 ${state.inventory.loot}`], ["EQUIPMENT", Object.values(state.equipment).map(id => equipmentCatalog.find(item => item.id === id)?.title || id).join(" // ")], ["NEURAL SLOTS", state.equippedSkills.length ? state.equippedSkills.map(id => skillCatalog.find(item => item.id === id)?.title || id).join(" // ") : "EMPTY"], ["COMBAT", c ? `${mission?.enemy || "TARGET"} // ${c.enemyHp}/${c.enemyMax} HP // ${c.energy}/3 ENERGY` : "NOT IN COMBAT"]]; $("valuesGrid").innerHTML = rows.map(([label, value]) => `<div class="value-row"><span>${label}</span><b>${value}</b></div>`).join(""); }
function renderContracts() { const completed = state.completedContracts || []; const active = [...new Map(contracts.filter(contract => !completed.includes(contract.id) && (contract.city || "glass") === (state.city || "glass")).map(contract => [contract.id, contract])).values()]; if (!active.some(contract => contract.id === state.contract)) state.contract = active[0]?.id || ""; $("taskCount").textContent = active.length; $("contractList").innerHTML = active.map(c => `<article class="contract ${state.contract === c.id ? "selected" : ""}" data-contract-id="${c.id}"><span class="contract-tag">${c.tag}</span><h4>${c.title}</h4><p>${c.desc}</p><div class="contract-foot"><span>₡ ${c.reward}</span><span>${c.difficulty} // ${c.xp} XP</span></div></article>`).join(""); document.querySelectorAll("[data-contract-id]").forEach(el => el.addEventListener("click", () => { if (state.combat) { toast("先完成目前遭遇"); return } state.contract = el.dataset.contractId; render(); addFeed("你鎖定了新合約。城市開始注意你。", "warn") })); }
function renderEquipment() { $("equipmentList").innerHTML = ["DECK", "WEAPON", "COAT"].map(slot => { const item = equipmentCatalog.find(entry => entry.id === state.equipment[slot]) || equipmentCatalog.find(entry => entry.slot === slot); const options = equipmentCatalog.filter(entry => entry.slot === slot).map(entry => `<option value="${entry.id}" ${entry.id === item.id ? "selected" : ""}>${entry.title}</option>`).join(""); return `<div class="loadout-slot"><div class="loadout-slot-head"><span>${item.icon} ${slot}</span><b>已裝備</b></div><select class="loadout-select" data-equipment-slot="${slot}" aria-label="選擇 ${slot} 裝備">${options}</select><small>${item.desc}</small></div>`; }).join(""); $("equipmentList").querySelectorAll("[data-equipment-slot]").forEach(select => select.addEventListener("change", () => equipEquipment(select.dataset.equipmentSlot, select.value))); }
function equipEquipment(slot, id) { const item = equipmentCatalog.find(entry => entry.id === id && entry.slot === slot); if (!item) return; state.equipment[slot] = id; addFeed(`${slot} 已裝備 ${item.title}。`, "warn"); toast(`${item.title} // EQUIPPED`); saveState(); render(); }
function renderEquippedSkills() { $("skillSlotCount").textContent = `${state.equippedSkills.length} / 2`; $("equippedSkills").innerHTML = [0, 1].map(index => { const skill = skillCatalog.find(item => item.id === state.equippedSkills[index]); return skill ? `<button class="equipped-skill" data-skill-toggle="${skill.id}"><span>${skill.icon}</span><b>${skill.title}</b><em>×</em></button>` : `<span class="skill-slot-empty">SLOT ${index + 1} // EMPTY</span>`; }).join(""); $("equippedSkills").querySelectorAll("[data-skill-toggle]").forEach(button => button.addEventListener("click", () => toggleSkill(button.dataset.skillToggle))); }
function renderInventoryActions() { $("inventoryActions").innerHTML = `<button class="inventory-btn" data-inventory="medkit" ${state.inventory.medkit < 1 ? "disabled" : ""}>＋ 體素針 <small>+25 VITAL</small></button><button class="inventory-btn" data-inventory="medbox" ${state.inventory.medbox < 1 ? "disabled" : ""}>▣ 醫療箱 <small>+55 VITAL</small></button><button class="inventory-btn" data-inventory="ramCell" ${state.inventory.ramCell < 1 ? "disabled" : ""}>⌁ RAM 電池 <small>回充 RAM</small></button><button class="inventory-btn" data-inventory="loot" ${state.inventory.loot < 1 ? "disabled" : ""}>◆ 開黑盒 <small>隨機獎勵</small></button>`; document.querySelectorAll("[data-inventory]").forEach(button => button.addEventListener("click", () => useInventory(button.dataset.inventory))); }
function renderCombatSkills() { const panel = $("combatPanel"); if (!panel) return; let bar = $("skillActions"); if (!bar) { bar = document.createElement("div"); bar.id = "skillActions"; bar.className = "skill-actions"; const actions = panel.querySelector(".combat-actions"); actions?.parentElement.appendChild(bar); } let heading = $("combatSkillHeading"); if (!heading) { heading = document.createElement("div"); heading.id = "combatSkillHeading"; heading.className = "combat-skill-heading"; bar.parentElement.insertBefore(heading, bar); } let picker = $("combatSkillPicker"); if (!picker) { picker = document.createElement("div"); picker.id = "combatSkillPicker"; picker.className = "combat-skill-picker"; picker.hidden = true; bar.parentElement.insertBefore(picker, bar); } const skills = state.equippedSkills.map(id => skillCatalog.find(skill => skill.id === id)).filter(Boolean); const actionMap = { phase: "guard", parasite: "hack", echo: "strike", decoy: "guard" }; heading.innerHTML = `<span>NEURAL ACTIVE SKILLS // ${skills.length}/2</span><button type="button" id="swapCombatSkills">更換技能</button>`; bar.innerHTML = skills.map(skill => `<button class="skill-action-btn" data-skill-action="${skill.id}"><b>${skill.icon} ${skill.title}</b><small>ACTIVE // USES ${actionMap[skill.id].toUpperCase()}</small></button>`).join(""); picker.innerHTML = state.skills.map(id => { const skill = skillCatalog.find(item => item.id === id); const equipped = state.equippedSkills.includes(id); return `<button type="button" data-combat-pick="${id}">${skill.icon} ${skill.title}${equipped ? " // EQP" : ""}</button>`; }).join(""); $("swapCombatSkills").addEventListener("click", () => { picker.hidden = !picker.hidden; }); picker.querySelectorAll("[data-combat-pick]").forEach(button => button.addEventListener("click", () => { if (state.combat?.busy) return toast("敵方回合中，暫時無法更換"); const id = button.dataset.combatPick; const slot = state.equippedSkills.indexOf(id); if (slot >= 0) state.equippedSkills.splice(slot, 1); else if (state.equippedSkills.length < 2) state.equippedSkills.push(id); else state.equippedSkills[0] = id; picker.hidden = true; addFeed(`${skillCatalog.find(skill => skill.id === id).title} 已切換至戰鬥快捷欄。`, "warn"); saveState(); render(); })); bar.querySelectorAll("[data-skill-action]").forEach(button => button.addEventListener("click", () => { const skill = button.dataset.skillAction; addFeed(`${skill} 已啟用。`, "warn"); combatAction(actionMap[skill]); })); }
function useInventory(id) { const maxHp = 100 + (state.upgrades.includes("plating") ? 15 : 0); if (id === "medkit" && state.inventory.medkit > 0) { state.inventory.medkit -= 1; state.hp = clamp(state.hp + 25, 0, maxHp); toast("體素針使用 // VITAL +25"); addFeed("你在街角使用體素針，傷口暫時閉合。", "warn"); } else if (id === "medbox" && state.inventory.medbox > 0) { state.inventory.medbox -= 1; state.hp = clamp(state.hp + 55, 0, maxHp); toast("醫療箱使用 // VITAL +55"); addFeed("你打開醫療箱，止血泡沫覆蓋了傷口。", "warn"); } else if (id === "ramCell" && state.inventory.ramCell > 0) { state.inventory.ramCell -= 1; state.ram = 100; toast("RAM 電池使用 // RAM FULL"); addFeed("RAM 電池接入，神經噪音恢復穩定。", "warn"); } else if (id === "loot") { openLootBox(); return; } else return; saveState(); render(); }
function cycleEquipment(currentId) { const current = equipmentCatalog.find(item => item.id === currentId); const options = equipmentCatalog.filter(item => item.slot === current.slot); const next = options[(options.findIndex(item => item.id === currentId) + 1) % options.length]; state.equipment[current.slot] = next.id; addFeed(`${current.slot} 已切換為 ${next.title}。`); toast(`${next.title} // EQUIPPED`); saveState(); render(); }
function toggleSkill(id) { const index = state.equippedSkills.indexOf(id); if (index >= 0) state.equippedSkills.splice(index, 1); else if (state.equippedSkills.length < 2) state.equippedSkills.push(id); else { state.equippedSkills[0] = id; } addFeed(index >= 0 ? `${id} 已卸下。` : `${id} 已裝入神經快捷欄。`); saveState(); render(); }
function renderMarket() { const city = cities.find(item => item.id === state.city) || cities[0]; const cycle = Math.floor(Date.now() / 120000); const rotated = marketItems.map((item, index) => ({ ...item, price: item.price + ((cycle + index) % 3) * 20 + (city.id === "rust" ? 10 : city.id === "void" ? -5 : 0) })); const items = rotated.map(item => `<div class="market-item"><span class="item-icon">${item.icon}</span><span><b>${item.title}</b><small>${item.desc} // 持有 ${Math.max(0, Number(state.inventory[item.id]) || 0)}</small></span><button class="buy-btn" data-market="${item.id}" ${state.credits < item.price ? "disabled" : ""}>₡ ${item.price}</button></div>`).join(""); const combatActions = combatActionCatalog.filter(action => action.price && !state.combatActions.includes(action.id)).map(action => `<div class="market-item skill-row combat-action-market"><span class="item-icon">${action.icon}</span><span><b>${action.title}</b><small>${action.desc} // COMBAT ACTION</small></span><button class="buy-btn" data-market="combat:${action.id}" ${state.credits < action.price ? "disabled" : ""}>₡ ${action.price}</button></div>`).join(""); const skills = skillCatalog.map(skill => { const learned = state.skills.includes(skill.id); return `<div class="market-item skill-row"><span class="item-icon">${skill.icon}</span><span><b>${skill.title}</b><small>${skill.desc} // ${learned ? "已學習" : "技能晶片"}</small></span><button class="buy-btn ${learned ? "sell-btn" : ""}" data-market="${learned ? `sellSkill:${skill.id}` : `skill:${skill.id}`}" ${!learned && state.credits < skill.price ? "disabled" : ""}>${learned ? "出售 +₡" + Math.floor(skill.price * .45) : "₡ " + skill.price}</button></div>`; }).join(""); $("marketList").innerHTML = `<div class="market-cycle">${city.market} // ROTATION ${String(cycle % 99).padStart(2, "0")} // 新貨每 02:00</div>${items}${combatActions}${skills}<div class="market-item sell-row"><span class="item-icon">◆</span><span><b>黑盒戰利品</b><small>未開 ${Math.max(0, Number(state.inventory.loot) || 0)} // 開啟可獲得物資或技能晶片</small></span><button class="buy-btn" data-market="openLoot" ${state.inventory.loot < 1 ? "disabled" : ""}>開啟</button><button class="buy-btn sell-btn" data-market="sellLoot" ${state.inventory.loot < 1 ? "disabled" : ""}>出售 ₡140</button></div>`; document.querySelectorAll("[data-market]").forEach(button => button.addEventListener("click", () => tradeMarket(button.dataset.market))); }
