function moveToDistrictPoint(index) { if (state.combat) return toast("戰鬥中無法移動"); state.districtPoint = index; const city = cities.find(item => item.id === state.city) || cities[0]; const point = city.points[index]; const map = document.querySelector(".district-map"); if (map) { let location = $("districtLocation"); if (!location) { location = document.createElement("div"); location.id = "districtLocation"; location.className = "district-location"; map.after(location); } location.style.cssText = "border:1px solid #263746;background:#0d1720;padding:9px 10px;margin:-7px 0 14px;display:grid;gap:4px"; location.innerHTML = `<b style="color:#3de5d0;font-size:11px">${point.name}</b><span style="color:#dce8e7;font-size:9px">${point.type} // ${point.action}</span><small style="color:#738391;font-size:8px;line-height:1.5">${point.desc}</small>`; } addFeed(`你移動到 ${point.name}：${point.action}。`, "warn"); toast(`${point.name} // ${point.action}`); renderDistrict(); saveState(); }
